import{_ as t,o as s,c as a,a2 as i}from"./chunks/framework.BvlN9b-o.js";const u=JSON.parse('{"title":"Quick start: backend development","description":"","frontmatter":{"docLocale":"en","counterpart":"/getting-started/quickstart","contentType":"guide","prev":{"text":"Create your project","link":"/en/getting-started/create-project"},"next":{"text":"Project structure","link":"/en/architecture/project-structure"}},"headers":[],"relativePath":"en/getting-started/quickstart.md","filePath":"en/getting-started/quickstart.md"}'),n={name:"en/getting-started/quickstart.md"};function r(o,e,d,p,h,l){return s(),a("div",null,[...e[0]||(e[0]=[i(`<h1 id="quick-start-backend-development" tabindex="-1">Quick start: backend development <a class="header-anchor" href="#quick-start-backend-development" aria-label="Permalink to &quot;Quick start: backend development&quot;">​</a></h1><p>Start the API and dependencies, verify HTTP, PostgreSQL and migrations, then begin your own business module.</p><h2 id="_1-prepare-tools-and-a-copy" tabindex="-1">1. Prepare tools and a copy <a class="header-anchor" href="#_1-prepare-tools-and-a-copy" aria-label="Permalink to &quot;1. Prepare tools and a copy&quot;">​</a></h2><p>Use the repository versions: Rust 1.96.0, Node 24.18.0, pnpm 11.17.0, just 1.58.0 and Docker / Compose for Linux containers. Sources are <code>rust-toolchain.toml</code>, <code>.node-version</code>, <code>package.json</code> and <code>.tool-versions</code>.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/CaiZongyuan/axum-saas-template.git</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> axum-saas-template</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --frozen-lockfile</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span></span></code></pre></div><p>Run from the repository root. The first run downloads dependencies and compiles Rust. The script starts PostgreSQL, Redis, RustFS and Mailpit, applies migrations and initializes storage, then runs API, Worker and Web.</p><p>Without <code>.env</code>, development defaults come from <code>.env.example</code>. Keep local overrides in <code>.env</code>. See the <a href="./../reference/config">configuration reference</a>.</p><h2 id="_2-make-a-real-request" tabindex="-1">2. Make a real request <a class="header-anchor" href="#_2-make-a-real-request" aria-label="Permalink to &quot;2. Make a real request&quot;">​</a></h2><p>Keep development running and execute in another terminal:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://127.0.0.1:18000/health/live</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://127.0.0.1:18000/health/ready</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://127.0.0.1:18000/api/v1/system/status</span></span></code></pre></div><p>Expect HTTP 200 and an <code>x-request-id</code> on every response. Status returns <code>status: &quot;ok&quot;</code>, <code>database: &quot;connected&quot;</code> and the actual <code>schema_version</code>, which changes with migrations.</p><p>Liveness proves the process is running; readiness validates dependencies and the full migration set. Starting the API does not migrate the database.</p><h2 id="_3-observe-failure-and-recovery" tabindex="-1">3. Observe failure and recovery <a class="header-anchor" href="#_3-observe-failure-and-recovery" aria-label="Permalink to &quot;3. Observe failure and recovery&quot;">​</a></h2><p>Use your own development environment. Stop PostgreSQL in another terminal:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> db-down</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://127.0.0.1:18000/health/ready</span></span></code></pre></div><p>Readiness becomes 503 while liveness remains 200. Restore the database:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> services-up</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://127.0.0.1:18000/health/ready</span></span></code></pre></div><p>Readiness should return 200. If connections work but migration history differs, run <code>just migrate</code> and check source/database versions.</p><h2 id="_4-prepare-authenticated-requests" tabindex="-1">4. Prepare authenticated requests <a class="header-anchor" href="#_4-prepare-authenticated-requests" aria-label="Permalink to &quot;4. Prepare authenticated requests&quot;">​</a></h2><p>The default Web origin is <code>http://127.0.0.1:15400</code>. Create a development account at <code>/register</code>: the first successful account is Owner, later accounts are Members. Passwords use 12–128 characters.</p><p>Your protected HTTP endpoints reuse current Session, trusted Origin and CSRF. See <a href="./../tutorials/sessions">authentication and sessions</a>. View development recovery mail in <a href="http://127.0.0.1:18025" target="_blank" rel="noreferrer">Mailpit</a>.</p><p>The knowledge example provides complete <a href="./../tutorials/personal-documents">business writes</a>, <a href="./../tutorials/library-grants">resource authorization</a> and <a href="./../tutorials/document-exports">background exports</a> to inspect while building your own business.</p><h2 id="_5-enter-the-development-loop" tabindex="-1">5. Enter the development loop <a class="header-anchor" href="#_5-enter-the-development-loop" aria-label="Permalink to &quot;5. Enter the development loop&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> generate</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> contracts:check</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> boundaries:check</span></span></code></pre></div><p>Rust DTOs own the contract; SDK and types come from OpenAPI. Add your module, migrations, routes and tests together. Read <a href="./../architecture/project-structure">project structure</a>, then <a href="./../guides/new-module">add a business module</a>.</p><p>Rust <code>.rs</code> / <code>.toml</code> changes restart API and Worker. After adding SQL migrations, run <code>just migrate</code> and restart development to refresh the migration set embedded in the binaries. Web uses HMR.</p><h2 id="stop-and-troubleshoot" tabindex="-1">Stop and troubleshoot <a class="header-anchor" href="#stop-and-troubleshoot" aria-label="Permalink to &quot;Stop and troubleshoot&quot;">​</a></h2><p><code>Ctrl+C</code> stops host API/Worker/Web. <code>just services-down</code> stops dependencies and preserves volumes.</p><table tabindex="0"><thead><tr><th>Symptom</th><th>Check and recovery</th></tr></thead><tbody><tr><td>Docker dependencies not ready</td><td>Check daemon, images and ports; restart development</td></tr><tr><td>Readiness is 503</td><td>Check PostgreSQL, explicit migrations and source checksums</td></tr><tr><td>API or Web port busy</td><td>Change APP_PORT or WEB_PORT in .env; development scripts derive the endpoints</td></tr><tr><td>Database port changed</td><td>Change POSTGRES_PORT in .env; DATABASE_URL is derived automatically</td></tr><tr><td>Healthy without a port binding</td><td>Startup fails before migration; stop the reported owner and force-recreate while preserving volumes</td></tr><tr><td>Request fails</td><td>Use request_id to find API JSON logs and check the public error</td></tr></tbody></table><p>Run <code>just docs</code> for local documentation at <code>http://127.0.0.1:5174/axum-saas-template/docs/</code>. The footer SHA identifies the build source; check out that commit to reproduce a specific version.</p><hr><p>Source version：<code>e87f840d6dfc</code> · <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e87f840d6dfcfb1436042f731d0c0d7d5cadc9b2/docs/getting-started/quickstart.en.md" target="_blank" rel="noreferrer">Page Markdown</a></p>`,32)])])}const k=t(n,[["render",r]]);export{u as __pageData,k as default};
